head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[checkcombobox > M > addItem]<br/>컴포넌트에 신규 아이템을 추가합니다.",
    "validation" : [    
        "아이템이 BindItemSet 으로 정의된 경우에 동작합니다."    ,
        "value(필수) 파라미터로 추가하는 아이템의 Value 값을 문자열로 설정합니다.",
        "label(필수) 파라미터로 추가하는 아이템의 Label 값을 문자열로 설정합니다.",
        "index(선택) 파라미터로 아이템이 추가될 위치를 인덱스로 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "설정한 인덱스 위치에 아이템이 추가되고 이후 아이템의 인덱스가 하나씩 증가합니다.",
        "파라미터를 설정하지 않거나 전체 아이템 갯수보다 크게 설정하면 마지막 위치에 추가됩니다.",
        "아이템이 추가된 위치의 인덱스값을 반환합니다.",
        "아이템이 BindItemSet 으로 정의된 경우 추가된 아이템은 DataCollection 에 반영되지 않습니다."
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange"]);

    // target 생성
    $c.gcm.createLabel('label="addItem 후 추가된 아이템 클릭하여 값 확인"', '', 'label1');
    $c.gcm.createBasicCheckComboBox('', eList);
}



scwin.btn_addItem_onclick = function (e) {
    let value = par_value.getValue();
    let label = par_label.getValue();
    let index = par_index.getValue();
    let rtn = '';

    if (index == '')
	    rtn = target1.addItem(value, label);
    else
        rtn = target1.addItem(value, label, index);

    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
};



scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + target1.getText());
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + target1.getSelectedIndex());
}



scwin.btn_getDataList_onclick = function (e) {
	// let rsData  = dlt_ref.getAllJSON();
    let rsData = gdl_checkcombobox.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("label 값 : " + rsData[i].label);
    }
};
